// Mode pointeur (touche l) : le clic cesse de naviguer, le curseur devient un marqueur ambre,
// et maintenir le bouton trace un trait qui s'efface en ~1,2 s. Sortie par l ou Échap.
const dot=document.querySelector('.laser-dot');
const ink=document.querySelector('.ink');
const ctx=ink.getContext('2d');
const hint=document.querySelector('.hint');
const HINT_NAV='← → naviguer · f plein écran · l pointeur';
const HINT_LASER='<b>pointeur</b> · clic pour souligner · l ou Échap pour sortir';
let laser=false, drawing=false, prev=null;
function sizeInk(){
  const r=window.devicePixelRatio||1;
  ink.width=innerWidth*r; ink.height=innerHeight*r;
  ctx.setTransform(r,0,0,r,0,0);
  ctx.lineCap='round'; ctx.lineJoin='round'; ctx.lineWidth=5;
  ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();
}
function fade(){
  if(!laser) return;
  ctx.save();
  ctx.globalCompositeOperation='destination-out';
  ctx.fillStyle='rgba(0,0,0,0.06)';
  ctx.fillRect(0,0,innerWidth,innerHeight);
  ctx.restore();
  requestAnimationFrame(fade);
}
function setLaser(on){
  laser=on; drawing=false; prev=null;
  document.body.classList.toggle('laser',on);
  hint.innerHTML=on?HINT_LASER:HINT_NAV;
  if(on){ sizeInk(); requestAnimationFrame(fade); }
  else { ctx.clearRect(0,0,innerWidth,innerHeight); }
}
addEventListener('resize',()=>{ if(laser) sizeInk(); });
document.addEventListener('mousemove',e=>{
  if(!laser) return;
  dot.style.left=e.clientX+'px'; dot.style.top=e.clientY+'px';
  if(drawing){
    if(prev){ ctx.beginPath(); ctx.moveTo(prev.x,prev.y); ctx.lineTo(e.clientX,e.clientY); ctx.stroke(); }
    prev={x:e.clientX,y:e.clientY};
  }
});
document.addEventListener('mousedown',e=>{ if(laser){ drawing=true; prev={x:e.clientX,y:e.clientY}; } });
document.addEventListener('mouseup',()=>{ drawing=false; prev=null; });
document.addEventListener('keydown',e=>{
  if(['ArrowRight',' ','PageDown'].includes(e.key)){e.preventDefault();show(i+1);}
  else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(i-1);}
  else if(e.key==='f'){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.();}
  else if(e.key==='l'){setLaser(!laser);}
  else if(e.key==='Escape'&&laser){setLaser(false);}
});
document.addEventListener('click',e=>{ if(laser) return; show(i + (e.clientX < window.innerWidth*0.25 ? -1 : 1));});

