// Sans taille CSS explicite, un canvas garde sa taille intrinseque (= buffer) et la trace derive.
const geo = await p.evaluate(() => {
  const r = document.querySelector('.ink').getBoundingClientRect();
  const c = document.querySelector('.ink');
  return { w: Math.round(r.width), h: Math.round(r.height), bw: c.width, bh: c.height,
           vw: innerWidth, vh: innerHeight, dpr: devicePixelRatio };
});
ok.push([`boite CSS du canvas = viewport (${geo.w}x${geo.h} vs ${geo.vw}x${geo.vh})`, geo.w === geo.vw && geo.h === geo.vh]);
ok.push([`buffer = viewport x dpr (${geo.bw}x${geo.bh}, dpr ${geo.dpr})`, geo.bw === geo.vw * geo.dpr && geo.bh === geo.vh * geo.dpr]);

